"""Individually authored CTB review, after reading existing content and official sources."""
import copy,json,sys
from pathlib import Path
p=Path(sys.argv[1]);old=json.loads((p/'batch-02-existing.json').read_text());expected={r['unit']['unit_key']:r for r in old};rows={}
CTB='https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm'
STF='https://noticias.stf.jus.br/postsnoticias/stf-invalida-dispositivos-da-lei-dos-caminhoneiros-sobre-tempo-de-espera-jornada-e-descanso/'
LC211='https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp211.htm'
LC207='https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp207.htm'
R819='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao8192021.pdf'
R940='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao9402022.pdf'
L14440='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/lei/l14440.htm'
L14599='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14599.htm'
def add(n,case,variation,q1,q2,term,meaning,**patch):
 key='art-'+str(n);e=copy.deepcopy(expected[key]['explanation']);data={k:e[k] for k in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']}
 data.update(exemplo=case+' Variação: '+variation,prova=[q1,q2],termos=[dict(termo=term,significado=meaning)])
 data['pontos']+=patch.pop('extra_points',[]);data['atencao']+=patch.pop('notes',[]);data['remissoes']=list(dict.fromkeys([CTB,*data['remissoes'],*patch.pop('sources',[])]));data.update(patch);rows[key]=data
add(48,'Uma motocicleta estaciona perpendicularmente e junto ao meio-fio, sem sinalização diversa. Resposta: aplica-se a regra especial do §2º para veículo motorizado de duas rodas.', 'O motorista fica dentro do carro em local vedado: permanecer ao volante não libera estacionamento, conforme §3º.', 'A regra de estacionamento paralelo ao meio-fio é idêntica para todo veículo? Não. O §2º prevê posição perpendicular para motorizados de duas rodas, salvo sinalização diversa.', 'Manter o condutor dentro do veículo permite estacionar em qualquer local? Não. O §3º mantém a exigência de local previsto no CTB ou regulamentado por sinalização específica.', 'Posição de estacionamento','Orientação do veículo que distingue regra geral e exceção para duas rodas.',extra_points=['DUAS RODAS MOTORIZADAS: perpendicular e junto à guia, salvo outra sinalização.','Permanecer no veículo não afasta restrições de estacionamento.'])
add(49,'Uma passageira abre a porta sem observar a aproximação de um ciclista. Resposta: deve antes certificar-se de que não cria perigo para si ou outros usuários.', 'O condutor desembarca pelo lado da pista: a exceção relativa ao lado não dispensa conferir a segurança.', 'A exceção do condutor permite descer sem olhar o trânsito? Não. Excepciona o lado obrigatório de embarque/desembarque, mantendo o dever geral de segurança.', 'Só quem dirige deve conferir antes de abrir a porta? Não. O caput impõe o dever ao condutor e aos passageiros, inclusive para deixá-la aberta.', 'Abertura segura','Verificação prévia de risco, também para passageiros e ciclistas que passam.',notes=['Distinguir exceção do lado da calçada e dever de verificar perigo; a exceção não remove esse dever.'])
add(50,'O proprietário pretende usar a área junto à rodovia para acesso ao seu empreendimento. Resposta: esse uso precisa observar as condições de segurança do órgão com circunscrição sobre a via.', 'A propriedade do imóvel adjacente não torna irrelevante a segurança de quem circula na rodovia.', 'A faixa lateral de domínio pode ser usada sem observar a segurança viária? Não. O artigo vincula o uso às condições estabelecidas pelo órgão com circunscrição.', 'O art. 50 define sozinho uma distância universal para toda construção? Não. Trata das condições de segurança; não fixa neste dispositivo uma metragem única de afastamento.', 'Faixa de domínio','Área lateral da infraestrutura rodoviária, cujo uso se submete às regras competentes.',notes=['Não confundir faixa de domínio com faixa não edificável nem inventar largura ou afastamento neste artigo.'])
add(51,'O condomínio pretende implantar placas nas vias internas. Resposta: paga a implantação e a manutenção, mas deve obter aprovação prévia dos projetos pelo órgão com circunscrição.', 'A aprovação pública do projeto não transfere automaticamente as despesas de manutenção ao poder público.', 'Quem paga a sinalização regulamentadora nas vias internas do condomínio? O condomínio, inclusive a manutenção, conforme o recorte expresso do artigo.', 'A aprovação dos projetos pode ser omitida porque a via é interna? Não. O CTB condiciona implantação e manutenção à aprovação pelo órgão com circunscrição.', 'Às expensas','Custeado pelo condomínio; aprovação pública não elimina esse encargo.',notes=['Integrar art. 2º: vias internas de condomínios de unidades autônomas integram o alcance do CTB.'])
add(52,'Uma carroça circula numa via sem faixa especial. Resposta: segue pela direita, junto ao meio-fio ou acostamento, obedecendo às normas de circulação aplicáveis.', 'Se houver faixa especial destinada a esses veículos, não se aplica indiscriminadamente a posição subsidiária da pista.', 'Veículo de tração animal está livre das normas do CTB? Não. Seu condutor deve observá-las no que couber, além das normas do órgão competente.', 'A regra pela direita ignora a existência de faixa especial? Não. O artigo a vincula à ausência de faixa especial destinada aos veículos de tração animal.', 'Tração animal','Propulsão por animal, com regras próprias sem exclusão geral do CTB.',notes=['Não confundir veículo de tração animal com animal isolado, disciplinado pelo art. 53.'])
add(53,'Um guia conduz rebanho dividido em grupos moderados, separados para permitir passagem. Resposta: atende ao dever de não obstruir o trânsito, mantendo animais junto ao bordo quando na pista.', 'Dividir o rebanho não dispensa guia; o requisito também alcança um único animal em circulação.', 'A exigência de guia vale só para rebanhos grandes? Não. O caput alcança animais isolados ou em grupos, sem fixar quantidade mínima.', 'O CTB define um número exato de animais por grupo neste artigo? Não. Exige tamanho moderado e separação suficiente para não obstruir, sem número universal.', 'Guia do animal','Pessoa que conduz a circulação dos animais, distinta de guia física da calçada.',notes=['Não inventar quantidade máxima por grupo nem confundir guia de condução com meio-fio.'])
add(54,'O motociclista usa capacete, mas apenas óculos de sol comuns. Resposta: a Resolução 940/2022 não aceita óculos de sol isolados como substituto dos óculos de proteção.', 'A viseira pode ser levantada com o veículo imobilizado, devendo voltar à proteção dos olhos quando entrar em movimento.', 'Óculos de sol isolados substituem os protetores exigidos? Não. A Resolução 940, art. 4º, §2º, proíbe essa substituição, inclusive por óculos corretivos isolados.', 'Usar capacete basta para dispensar as demais condições do art. 54? Não. O artigo também exige condução com as duas mãos e vestuário conforme especificações do Contran, com integração das regras específicas.', 'Óculos de proteção','Equipamento próprio de proteção dos olhos, diferente de óculos comuns usados isoladamente.',notes=['Resolução 940/2022 em vigor desde 1º/4/2022; revogou 453/2013, 680/2017 e 846/2021.','Integrar art. 244, VII: a retirada de uma mão para indicar manobra é exceção específica; não gerar assertiva universal contraditória.'],sources=[R940])
add(55,'Uma passageira leva o capacete no braço durante o trajeto. Resposta: não cumpre o requisito; deve usá-lo devidamente fixado à cabeça, conforme Resolução 940.', 'Viajar no carro lateral acoplado é posição expressamente prevista, mas não dispensa capacete nem demais requisitos.', 'O passageiro pode ser transportado sobre o tanque da motocicleta? Não. O art. 55 prevê carro lateral acoplado ou assento suplementar atrás do condutor.', 'A exigência regulamentar de viseira ou proteção ocular alcança passageiros? Sim. A Resolução 940, art. 4º, aplica-se ao condutor e ao passageiro dos veículos abrangidos.', 'Assento suplementar','Posição prevista atrás do condutor, diferente de transporte improvisado.',notes=['Não ensinar dispensa de proteção dos olhos do passageiro pela ausência de repetição literal no inciso I; integrar Resolução 940/2022.','Limite etário e capacidade de cuidar da própria segurança têm disciplina própria no art. 244, V.'],sources=[R940])
add(57,'A faixa da direita é exclusiva de ônibus e existem outras faixas. Resposta: o ciclomotor usa a faixa adjacente à da direita, conforme o parágrafo único.', 'A falta de espaço no trânsito não permite subir na calçada urbana nem ingressar em via de trânsito rápido.', 'Ciclomotor pode circular em qualquer via urbana? Não. O caput proíbe via de trânsito rápido e circulação sobre calçadas urbanas.', 'Deve invadir a faixa da direita reservada exclusivamente a ônibus? Não. Quando há duas ou mais faixas, o parágrafo manda usar a faixa adjacente à da direita.', 'Faixa adjacente','Faixa ao lado da direita quando esta é exclusiva de outro tipo de veículo.',notes=['Não tratar todo veículo elétrico ou bicicleta elétrica como ciclomotor; enquadramento depende das definições e da regulamentação própria.'])
add(58,'Numa via urbana sem ciclovia, ciclofaixa ou acostamento utilizáveis, o ciclista segue junto ao bordo no sentido da via. Resposta: tem preferência sobre automotores nesse recorte.', 'Uma ciclofaixa existe, mas o contrafluxo não foi autorizado: a mera presença da faixa não dispensa autorização da autoridade competente.', 'O caput menciona indistintamente toda via rural? Não. O recorte textual é vias urbanas e rurais de pista dupla, sem ampliar automaticamente para qualquer via rural.', 'A autoridade pode autorizar contrafluxo em trecho sem ciclofaixa? Não pela exceção do parágrafo. Exige autorização e trecho dotado de ciclofaixa.', 'Contrafluxo autorizado','Circulação contrária ao fluxo automotor condicionada à ciclofaixa e autorização.',notes=['Preferência não dispensa cautela; não ampliar o âmbito rural do caput nem retirar a condição de autorização do parágrafo.'])
add(59,'O órgão autoriza e sinaliza passeio compartilhado para bicicletas. Resposta: há permissão no recorte do artigo, preservando a segurança dos usuários.', 'Se o ciclista desmonta e empurra a bicicleta, aplica-se a equiparação ao pedestre do art. 68, §1º, situação distinta de pedalar no passeio.', 'Apenas vontade do ciclista permite pedalar no passeio? Não. A circulação depende de autorização e sinalização pelo órgão com circunscrição.', 'Empurrar a bicicleta desmontado é igual a pedalar sem autorização? Não. O art. 68, §1º, equipara o ciclista desmontado empurrando a bicicleta ao pedestre.', 'Passeio autorizado','Espaço de circulação cujo uso montado por bicicleta depende das condições legais.',notes=['Distinguir bicicleta conduzida montada e desmontada; não negar a equiparação legal ao pedestre.'])
add(60,'Uma prova lista trânsito rápido, arterial, coletora e local como categorias urbanas. Resposta: o rol está correto; rodovias e estradas integram as rurais.', 'Chamar uma avenida de rápida no uso cotidiano não certifica sua classificação técnica como via de trânsito rápido.', 'Rodovia é categoria urbana do art. 60? Não. O inciso II classifica rodovias e estradas como vias rurais.', 'Nome popular de avenida basta para fixar a classificação da via? Não. É preciso examinar utilização e conceitos do Anexo I, sem deduzir toda categoria pelo nome.', 'Classificação da via','Categoria legal ligada à utilização, distinta do nome cotidiano do logradouro.',exemplo='Uma prova lista trânsito rápido, arterial, coletora e local como categorias urbanas. Resposta: o rol está correto; rodovias e estradas integram as rurais. Variação: chamar uma avenida de rápida no uso cotidiano não certifica sua classificação técnica.',notes=['O exemplo anterior não deve afirmar que toda avenida de ligação entre bairros é automaticamente arterial; conferir definição e características efetivas.'])
add(61,'Uma motocicleta circula em rodovia de pista dupla sem sinalização de velocidade. Resposta: integra o grupo de 110 km/h na redação da Lei 14.440/2022.', 'No mesmo tipo de rodovia existe placa regulamentando 80 km/h: não usar 110 como autorização para ignorar a placa.', 'Motocicleta sem placa em rodovia de pista simples tem limite geral de 90 km/h? Não. A redação atual a inclui no grupo de 100 km/h; 90 é para os demais veículos.', 'Os limites do §1º impedem sinalização de velocidade superior ou inferior? Não. O §2º autoriza regulamentação pelo órgão competente conforme as condições da via.', 'Limite subsidiário','Valor aplicável na ausência de sinalização regulamentadora, distinto do limite sinalizado.',atencao=['Lei 14.440/2022 incluiu motocicletas no grupo de 110/100 km/h; não repetir quadro antigo de 90 km/h para todas as motos.','Urbanas sem sinalização: 80/60/40/30; estradas: 60. Velocidade compatível pode precisar ser menor por segurança.'],sources=[L14440])
add(62,'Numa via com máxima de 80 km/h e condições normais, metade corresponde a 40 km/h. Resposta: esse cálculo deve ser integrado às condições operacionais previstas no artigo.', 'Congestionamento impede 40 km/h: a ressalva operacional evita ensinar obrigação de manter velocidade incompatível com o trânsito.', 'A mínima é sempre 40 km/h em qualquer via? Não. O parâmetro é metade da máxima estabelecida, respeitadas condições operacionais.', 'Toda velocidade inferior à metade gera automaticamente infração? Não. Integrar condições da via e trânsito e o art. 219, que tem requisitos e exceções próprios.', 'Metade condicionada','Referência relativa à máxima, com ressalva operacional e sem autuação automática.',notes=['Não transformar o cálculo em proibição absoluta durante congestionamento, chuva ou outras condições operacionais relevantes.'])
add(64,'Uma criança de oito anos e 1,30 m vai num automóvel particular. Resposta: deve ir atrás; pela Resolução 819, nessa faixa de idade pode usar o cinto previsto no anexo, não afirmar cadeirinha obrigatória para toda criança abaixo de dez anos.', 'Uma criança de oito anos já atingiu 1,45 m: não satisfaz a condição cumulativa de idade e altura do caput; conferir a regulamentação do banco dianteiro e demais cuidados.', 'Idade menor de dez anos, isoladamente, completa o requisito do caput? Não. A redação exige também que a criança não tenha atingido 1,45 m, com exceções regulamentadas.', 'Toda criança menor de dez anos deve usar cadeirinha, sem exceção? Não. A Resolução 819 distingue bebê conforto, cadeirinha, assento de elevação e cinto, considerando idade, peso, altura e limites do fabricante.', 'Retenção adequada','Sistema correspondente às condições da criança e do veículo, não cadeirinha universal.',atencao=['Lei 14.071/2020: idade inferior a 10 anos E altura ainda inferior a 1,45 m, com remissão ao Contran.','Resolução 819/2021 vigente desde 12/4/2021. Exceções de veículo e banco dianteiro não são dispensa geral de segurança.','Transporte remunerado individual: a isenção específica do art. 2º, §§2º/3º, aplica-se durante a efetiva prestação do serviço; não autoriza dispensa permanente do veículo.'],sources=[R819])
add(65,'Num trajeto curto dentro da cidade, passageiro do banco traseiro deixa de usar cinto. Resposta: curta duração e posição traseira não são exceções criadas pelo artigo.', 'Uma hipótese específica regulamentada pelo Contran deve ser analisada nos seus requisitos, sem presumir dispensa para qualquer passageiro.', 'O cinto é obrigatório só em rodovias? Não. O artigo abrange todas as vias do território nacional, para condutor e passageiros.', 'O art. 65 permite qualquer exceção escolhida pelo motorista? Não. A ressalva depende de situação regulamentada pelo Contran, não de preferência pessoal.', 'Exceção regulamentada','Hipótese definida pela autoridade competente, distinta de dispensa informal.',notes=['Não omitir a ressalva regulamentar nem inventar exceção para trajetos curtos.'])
add(67,'Os organizadores obtêm autorização da confederação para competir em via aberta. Resposta: ainda precisam da prévia permissão da autoridade com circunscrição e das outras condições legais.', 'Realizar apenas um ensaio da competição não dispensa o regime do caput.', 'Caução para dano à via substitui seguro em favor de terceiros? Não. Os incisos II e III têm objetos distintos e integram o conjunto de requisitos.', 'Os custos operacionais só podem ser recolhidos depois da prova? Não. O inciso IV exige prévio recolhimento, e o artigo também abrange os ensaios.', 'Caução ou fiança','Garantia de possíveis danos materiais à via, diferente do seguro para terceiros.',notes=['Lei 14.599/2023 substituiu a expressão por riscos e sinistros no inciso III, sem eliminar o seguro nem as demais condições.'],sources=[L14599])
add('67-a','Uma motorista profissional transporta passageiros em ônibus rodoviário. Resposta: integra o alcance do capítulo, assim como motorista profissional de cargas.', 'A definição do público abrangido não resolve sozinha todas as regras da jornada trabalhista; distinguir condução efetiva e tempo à disposição.', 'O capítulo alcança somente motorista de caminhão? Não. O rol inclui transporte rodoviário coletivo de passageiros e transporte rodoviário de cargas.', 'Os §§1º a 7º revogados ainda criam deveres neste artigo? Não. São marcações históricas de revogação; o §8º vetado também não cria regra vigente.', 'Tempo de condução','Período efetivamente ao volante, conceito que não esgota toda jornada de trabalho.',notes=['Redação e estrutura reorganizadas pela Lei 13.103/2015; ressalvar ADI 5322 nas regras de descanso do capítulo.'],sources=[STF])
add('67-c','Uma transportadora pretende dar oito horas de descanso contínuo e três em parcelas com base no §3º ainda exibido no compilado. Resposta: não ensinar essa autorização residual como vigente; o STF invalidou o fracionamento do descanso entre jornadas e sua coincidência com paradas obrigatórias na ADI 5322.', 'As pausas de 30 minutos na condução de carga ou passageiros têm recortes próprios nos §§1º/1º-A; não concluir que o STF aboliu toda pausa ou todo fracionamento desses intervalos.', 'É correto reproduzir como vigente o descanso diário de oito horas mais três fracionadas? Não. A ADI 5322 atingiu essa flexibilização; manter onze horas de descanso diário sem a autorização invalidada.', 'Cinco horas e meia ao volante equivalem ao limite total de toda jornada trabalhista? Não. O artigo trata de condução; jornada, espera e outras atividades precisam de integração ao regime trabalhista e à decisão.', 'Descanso entre jornadas','Repouso diário de onze horas, distinto das pausas de condução e da redação residual invalidada.',simples='O caput limita a condução contínua a cinco horas e meia. Cargas: 30 minutos de descanso dentro de seis horas; passageiros: 30 minutos a cada quatro horas. As pausas têm recortes próprios. No descanso diário de onze horas em 24 horas, NÃO reproduzir como autorização vigente o fracionamento/compensação residual do §3º: a ADI 5322 invalidou essa flexibilização. Condução efetiva não se confunde com toda jornada. Exceções de segurança e de pontos de parada exigem análise de seus requisitos.',pontos=['CONDUÇÃO CONTÍNUA: limite de 5h30.','CARGAS: 30 minutos dentro de 6 horas; PASSAGEIROS: 30 minutos a cada 4 horas, com regras próprias de pausa.','DESCANSO DIÁRIO: onze horas; ADI 5322 impede ensinar fracionamento entre jornadas e coincidência com paradas obrigatórias como autorização vigente.','§2º: situação excepcional justificada e registrada, tempo apenas necessário para local seguro, SEM comprometimento da segurança.','§§8º/9º: regulamentação sobre falta de pontos/vagas e publicação periódica de relação de espaços; não dispensa genérica.'],atencao=['INTERPRETAÇÃO/CONTROLE: notícia oficial STF de 5/7/2023, julgamento concluído em 30/6/2023, ADI 5322. O compilado conserva trecho com remissão à decisão; reprodução literal isolada induz erro.','Distinguir pausas ao volante, descanso entre jornadas e descanso semanal; não transformar tempo de espera em período universalmente fora da jornada.','Efeitos temporais e decisões posteriores devem ser consultados no processo; não aplicar a fatos antigos por automatismo nem certificar todas as hipóteses trabalhistas.'],sources=[STF,L14599])
add('67-e','O motorista registra a condução e preserva os dados do registrador. Resposta: o dever de controle e a responsabilidade pela guarda e exatidão são do condutor.', 'Uma empresa alega que qualquer falta de vaga dispensa punição em todo transporte: a exceção do §1º-A é específica para cargas e remete ao art. 67-C, §8º, com regulamentação.', 'O art. 67-E exige apenas tacógrafo em toda hipótese de controle? Não. O §2º também prevê diário de bordo, papeleta, ficha ou meios eletrônicos conforme norma do Contran.', 'O condutor pode alterar livremente os dados registrados? Não. O §3º exige funcionamento independente de sua interferência e o §4º lhe atribui guarda, preservação e exatidão.', 'Registro de condução','Controle do tempo ao volante, com meios legais e dados íntegros.',atencao=['§1º-A incluído pela Lei 14.440/2022: exceção específica de cargas, integrada ao §8º atual do art. 67-C.','Não tratar indisponibilidade de vaga como salvo-conduto universal; não recuperar automaticamente a redação de 2022 substituída em 2023.','Integrar ADI 5322 ao descanso; registrar dados não torna válida a autorização residual de fracionamento entre jornadas.'],sources=[L14440,L14599,STF])
add(68,'Sem acostamento utilizável numa via rural, pedestres andam pelos bordos em fila única, no sentido contrário aos veículos. Resposta: é o recorte do §3º, com prioridade e ressalvas de sinalização e segurança.', 'Na área urbana sem passeio, o §2º não repete a exigência rural de sentido contrário; não copiar essa condição para todo caso urbano.', 'O ciclista montado se equipara ao pedestre pelo §1º? Não. A equiparação exige estar desmontado e empurrando a bicicleta.', 'A prioridade autoriza andar na pista mesmo se a segurança ficar comprometida? Não. Os §§2º/3º ressalvam tanto locais proibidos pela sinalização quanto situações de segurança comprometida.', 'Equiparação ao pedestre','Direitos e deveres de quem desmonta e empurra a bicicleta, sem dispensar cautela.',simples='O pedestre usa passeios/passagens urbanas e acostamentos rurais. Sem espaço utilizável, pode usar os bordos da pista em fila única e com prioridade, respeitando proibição sinalizada e segurança. Nas vias RURAIS, segue em sentido CONTRÁRIO aos veículos. Ciclista desmontado empurrando bicicleta equivale ao pedestre. Obstruções exigem sinalização e proteção pelo órgão competente.',extra_points=['RURAL sem acostamento: sentido CONTRÁRIO aos veículos; não transportar automaticamente ao §2º urbano.','§5º: prever passeio nos trechos urbanos de vias rurais e nas obras de arte a construir; nessas condições, não usar acostamento.','§6º: órgão assegura sinalização e proteção diante de obstrução.'])
add(69,'Há faixa de travessia a exatamente cinquenta metros do pedestre. Resposta: deve utilizá-la, tomando precauções de visibilidade, distância e velocidade.', 'Iniciada a travessia, surge necessidade real de parar para evitar perigo: o inciso III proíbe demora ou parada SEM necessidade, não obriga continuar sob risco.', 'A distância de até cinquenta metros inclui exatamente cinquenta? Sim. O caput usa até, sem exigir que a faixa esteja a menos de cinquenta metros.', 'Nas interseções sem faixa, é permitido ampliar o percurso e demorar por vontade própria? Não. A travessia ocorre na continuação da calçada e não deve ser aumentada, demorada ou interrompida sem necessidade.', 'Travessia segura','Uso da passagem pertinente, integrado à sinalização e às precauções do pedestre.',notes=['Não retirar a expressão sem necessidade da proibição de parar; segurança continua relevante.'])
add(70,'O sinal muda liberando os carros enquanto uma pedestre ainda conclui a travessia. Resposta: mantém-se a preferência de quem ainda não terminou, conforme parágrafo único.', 'Pedestre que vai iniciar travessia em local semaforizado deve observar as indicações pertinentes; preferência de conclusão não significa livre início no vermelho.', 'A abertura do sinal dos veículos elimina a preferência de quem já atravessa? Não. O parágrafo único preserva a preferência até a conclusão da travessia.', 'A existência de faixa permite ignorar o semáforo em toda hipótese? Não. O caput ressalva locais semaforizados e manda observar as disposições do CTB.', 'Conclusão da travessia','Situação protegida mesmo com mudança do semáforo, distinta de iniciar passagem irregular.',notes=['Distinguir início conforme sinalização e preferência de conclusão; conversão à direita no vermelho não elimina a proteção do pedestre.'])
add(71,'Uma faixa fica apagada e sem visibilidade adequada. Resposta: o órgão com circunscrição tem dever de manutenção, não mera faculdade de repintar quando quiser.', 'A manutenção também abrange higiene e segurança das passagens, não apenas a tinta da faixa.', 'O dever do art. 71 se limita à pintura? Não. O texto reúne visibilidade, higiene, segurança e sinalização de faixas e passagens.', 'Qualquer órgão responde indistintamente pela manutenção de toda via? Não. O artigo identifica o órgão ou entidade com circunscrição sobre a via.', 'Manutenção da passagem','Dever que inclui condições de uso seguro, visibilidade, higiene e sinalização.',notes=['Não presumir competência municipal para toda rodovia apenas por existir travessia; examinar circunscrição.'])
add(72,'Uma cidadã protocola por escrito pedido de fiscalização perto de uma escola. Resposta: exerce direito próprio, sem depender de representar associação.', 'Sugerir mudança na lei não equivale a alterá-la por meio do pedido nem assegura deferimento automático.', 'Só entidade civil pode solicitar sinalização ou fiscalização? Não. Todo cidadão também possui o direito previsto, exercido por escrito.', 'O pedido obriga implantar exatamente a solução escolhida pelo requerente? Não. Há direito de solicitação e análise, integrado ao dever de resposta do art. 73.', 'Solicitação escrita','Forma do pedido legal, com direito à análise e resposta, sem deferimento automático.',notes=['Evitar transformar direito de pedir em aprovação obrigatória da proposta.'])
add(73,'O órgão recebe pedido de sinalização e conclui tecnicamente pela impossibilidade. Resposta: deve responder por escrito, esclarecendo ou justificando a análise.', 'Se for pertinente informar quando a solução ocorrerá, a resposta inclui essa previsão; não cabe ignorar o requerente.', 'O art. 73 fixa expressamente prazo de trinta dias para todos os pedidos? Não. O texto usa prazos mínimos, sem número universal neste artigo; não inventar prazo.', 'Uma resposta negativa dispensa justificativa? Não. Deve esclarecer ou justificar a análise da possibilidade de atendimento, conforme o caput.', 'Resposta motivada','Comunicação escrita que explica a análise, inclusive quando não há atendimento.',notes=['A literalidade prazos mínimos não contém quantidade; verificar regime administrativo aplicável antes de ensinar prazo fechado.'])
add(74,'Um órgão do SNT declara facultativa sua coordenação educacional. Resposta: o §1º determina existência obrigatória em cada órgão ou entidade.', 'O executivo promove Escola Pública de Trânsito mediante convênio: é modalidade admitida, não precisa ser exclusivamente dentro da estrutura.', 'Educação para o trânsito é dever secundário do SNT? Não. O caput a declara direito de todos e dever prioritário dos componentes.', 'O funcionamento das Escolas Públicas só pode ocorrer por estrutura própria? Não. O §2º admite estrutura organizacional ou convênio, conforme moldes e padrões do Contran.', 'Dever prioritário','Educação como obrigação central do sistema, com coordenação obrigatória.',extra_points=['Escolas Públicas: órgãos EXECUTIVOS, estrutura própria OU convênio; não trocar com faculdade de coordenação.'])
add(75,'O Contran define os temas anuais e o órgão local promove campanha adicional adequada à região. Resposta: campanhas nacionais e locais coexistem; a local não substitui o cronograma nacional.', 'A obrigação textual de difusão gratuita refere-se aos serviços explorados pelo poder público, não presumir imposição idêntica a toda emissora privada por este parágrafo.', 'Anualidade dos temas torna as campanhas apenas ocasionais? Não. O §2º atribui caráter permanente, com atenção especial aos períodos indicados.', 'O §2º menciona toda emissora privada como obrigada à difusão gratuita? Não. O recorte expresso é serviço de rádio e difusão de sons/imagens explorado pelo poder público.', 'Campanha permanente','Atuação continuada, compatível com definição anual de temas e cronogramas.',notes=['Não ampliar obrigação do §2º para todo veículo privado de comunicação; distinguir definição anual e permanência.'])
add(76,'Uma universidade coordena plano de redução de sinistros com seu núcleo interdisciplinar. Resposta: corresponde ao inciso IV, integrado à cooperação entre educação e trânsito.', 'Uma escola de formação de professores inclui conteúdos e treinamento: é hipótese do inciso II, não exigência textual de criar curso de especialização.', 'O art. 76 limita a educação de trânsito ao ensino superior? Não. O caput abrange pré-escola e os graus de ensino que nomeia, com coordenação entre sistemas.', 'O inciso IV atual manda criar cursos de especialização? Não. Prevê planos de redução de sinistros com núcleos universitários; não inserir obrigação que esse texto não contém.', 'Interdisciplinaridade','Integração de áreas do ensino e da sociedade na educação e prevenção viária.',simples='Educação para o trânsito ocorre nos níveis citados no caput mediante ações coordenadas. O Ministério da Educação, por proposta do Contran e do Conselho de Reitores, promove currículo interdisciplinar, conteúdo e treinamento para formação docente, corpos técnicos interprofissionais de análise estatística e planos de redução de sinistros com núcleos universitários. Não atribuir ao texto criação obrigatória de cursos de especialização.',atencao=['Lei 14.599/2023 atualizou o parágrafo e o inciso IV, usando sinistros. A nomenclatura de graus do caput é histórica, mas a abrangência não se restringe ao superior.'],sources=[L14599])
add(77,'O Ministério da Saúde estabelece, por proposta do Contran, campanha sobre primeiros socorros após sinistros. Resposta: é a competência do caput, com caráter permanente pelo SUS.', 'Estudar a competência da campanha não autoriza ensinar técnica médica improvisada nem impor intervenção perigosa ao candidato.', 'O Contran sozinho ocupa o lugar do Ministério da Saúde nesta campanha? Não. Sua função textual é de proposta; a instituição da campanha cabe ao Ministério da Saúde.', 'O caráter permanente dispensa qualquer intensificação? Não. O parágrafo prevê intensificação nos períodos e forma da remissão legal.', 'Campanha de primeiros socorros','Educação pública sob competência da Saúde, por proposta do Contran.',notes=['Lei 14.599/2023 atualizou a redação para sinistros. Preservar a remissão literal do parágrafo ao art. 76, sem reescrevê-la como se o compilado apontasse outro número.'],sources=[L14599])
add('77-a','Uma peça publicitária contém mensagem educativa. Resposta: integra mecanismo suplementar às campanhas oficiais, não substitui programas do SNT.', 'Mesmo com divulgação comercial educativa, os deveres de campanhas dos arts. 75 e 77 continuam.', 'Mensagem em publicidade substitui as campanhas oficiais? Não. O art. 77-A assegura mecanismos em caráter suplementar às campanhas dos arts. 75 e 77.', 'O artigo exige atuação restrita a uma cidade? Não. O caput menciona veiculação em todo território nacional pelos mecanismos dos arts. 77-B a 77-E.', 'Suplementar','Que acrescenta instrumento às campanhas existentes, sem eliminar seus deveres.',notes=['Incluído pela Lei 12.006/2009; distinguir norma original de 1997 e mecanismo posterior.'])
add('77-b','Um revendedor autorizado promove comercial televisivo de veículo. Resposta: é equiparado ao fabricante pelo §3º e deve integrar mensagem educativa no recorte do artigo.', 'A venda de peças e acessórios também integra o rol de produtos; não reduzir a obrigação apenas ao anúncio do veículo completo.', 'Só o fabricante original é alcançado pelo §2º? Não. O §3º equipara montador, encarroçador, importador e revendedor autorizado dos produtos abrangidos.', 'O §2º enuncia qualquer anúncio de qualquer produto em qualquer mídia? Não. Especifica propaganda comercial por iniciativa do fabricante/equiparados e rádio, televisão, jornal, revista ou outdoor; o art. 77-C tem extensão própria.', 'Fabricante equiparado','Sujeito que recebe o mesmo tratamento do fabricante no recorte do §3º.',simples='Publicidade de produtos da indústria automobilística ou afim deve incluir mensagem educativa conjuntamente veiculada. O rol abrange veículos rodoviários automotores, peças, componentes e acessórios. O §2º especifica propaganda comercial do fabricante em rádio, TV, jornal, revista e outdoor; o §3º equipara montador, encarroçador, importador e revendedor autorizado. Não ampliar automaticamente esses recortes a qualquer anunciante ou meio.',atencao=['Não confundir o recorte do §2º com a extensão específica de outdoors à margem de rodovia do art. 77-C.','Inclusão pela Lei 12.006/2009; o artigo não autoriza cada anunciante a escolher livremente o padrão da mensagem.'])
add('77-c','Um outdoor de campanha eleitoral fica à margem de rodovia, fora da faixa de domínio. Resposta: a extensão do artigo ainda exige mensagem educativa.', 'A regra não exige que o anúncio seja de automóvel nem que esteja dentro da faixa de domínio.', 'Outdoor rodoviário eleitoral está excluído porque não vende carro? Não. A extensão alcança qualquer produto e anunciante, inclusive publicidade institucional ou eleitoral.', 'Estar fora da faixa de domínio elimina a obrigação deste artigo? Não. O caput expressamente abrange instalação dentro ou fora dessa faixa, à margem de rodovia.', 'Extensão rodoviária','Ampliação da mensagem educativa para outdoors à margem de rodovia.',notes=['Não ampliar essa extensão específica para toda mídia ou localização sem confrontar o art. 77-B.'])
add('77-d','Um anunciante quer usar qualquer frase e tamanho sem observar o padrão competente. Resposta: conteúdo, apresentação e procedimentos são especificados pelo Contran.', 'A autonomia de uma campanha local não elimina as diretrizes nacionais do art. 75 para essas mensagens.', 'Cada anunciante define sozinho o padrão jurídico da mensagem? Não. O artigo atribui ao Contran especificar conteúdo, padrão e procedimentos de veiculação.', 'A atribuição dispensa observar as diretrizes das campanhas do art. 75? Não. O próprio caput exige conformidade com essas diretrizes.', 'Padrão de apresentação','Forma regulamentada da mensagem educativa, distinta de livre escolha do anunciante.',notes=['Não inventar neste artigo uma frase anual ou dimensão obrigatória sem conferir a resolução específica.'])
add('77-e','Uma peça irregular é imediatamente suspensa até cumprir as exigências. Resposta: essa medida do §2º não se confunde com a suspensão de outras propagandas do produto, de até sessenta dias, no inciso II.', 'Reincidência pode multiplicar a multa do dobro ao quíntuplo, mas não obriga automaticamente aplicar juntas todas as sanções.', 'A suspensão de até sessenta dias é a única consequência de qualquer publicidade irregular? Não. O §2º ainda determina suspensão imediata da peça até regularização, distinta da sanção do inciso II.', 'O texto obriga aplicação cumulativa de todas as sanções? Não. O §1º permite isolada ou cumulativamente conforme regulamento; a multa textual vai de R$ 1.627 a R$ 8.135.', 'Suspensão da peça','Cessação imediata até adequação, distinta da suspensão sancionatória de outras propagandas.',pontos=['Advertência por escrito.','Inciso II: suspensão de OUTRA propaganda do produto nos veículos de divulgação, até 60 dias.','Multa textual: R$ 1.627 a R$ 8.135; reincidência: dobro até quíntuplo.','§1º: isoladas OU cumulativas, conforme regulamento.','§2º: imediata suspensão da peça irregular ATÉ adequação.'],notes=['Não trocar suspensão da peça e suspensão de outras propagandas nem afirmar cumulação obrigatória.'])
add(78,'Uma candidata lê a referência ao SPVAT no parágrafo e conclui que o seguro está sendo cobrado hoje. Resposta: essa conclusão é indevida; a LC 211/2024 revogou a LC 207 que o instituiu, com vigência na publicação de 31/12/2024.', 'O caput sobre programas de prevenção de sinistros permanece estudável; a ressalva financeira não elimina toda atuação preventiva dos ministérios.', 'A menção residual ao SPVAT prova obrigação atual de pagar esse seguro? Não. Deve ser integrada à revogação da LC 207 pela LC 211, sem criar cobrança atual pela leitura isolada.', 'Revogar o regime do SPVAT restaura automaticamente o regime antigo do DPVAT? Não. A revogação não provoca repristinação automática; não ensinar retorno obrigatório do antigo seguro sem norma específica.', 'Texto residual','Referência ainda exibida no compilado que exige integração ao regime revogado.',simples='O caput prevê programas de prevenção de sinistros pelos ministérios indicados, por intermédio do Contran. O parágrafo conserva referência a repasse mensal de até 5% de valores destinados à Seguridade Social dos prêmios do SPVAT, inserida pela LC 207/2024. ALERTA: a LC 211/2024 revogou a LC 207, vigente essa revogação desde 31/12/2024. Não usar o trecho residual para afirmar cobrança ou arrecadação atual do SPVAT, nem retorno automático do DPVAT.',pontos=['Caput: Saúde, Educação, Trabalho e Emprego, Transportes e Justiça e Segurança Pública, por intermédio do Contran.','Parágrafo textual: até 5% dos valores destinados à Seguridade Social dos PRÊMIOS do SPVAT; não 5% de toda arrecadação de trânsito.','LC 207/2024 instituidora REVOGADA pela LC 211/2024, art. 4º, desde publicação em 31/12/2024.','Distinguir referência residual, regime de seguro, programas preventivos e eventual direito relativo a eventos históricos.'],atencao=['Não criar exercício que pressuponha arrecadação atual de SPVAT apenas porque o parágrafo permanece no compilado.','A revogação da lei modificadora não equivale automaticamente a retirar toda redação incorporada nem a restaurar a lei antiga; distinguir regime material extinto e texto residual.','Não certificadas todas as regras de indenizações relativas a sinistros históricos.'],sources=[LC211,LC207])
add(79,'O Detran firma convênio com a secretaria estadual de educação para desenvolver formação. Resposta: é instrumento facultativo para cumprir obrigações educacionais.', 'O órgão não firma convênio: isso não transforma o dever prioritário de educação em facultativo.', 'Poderão firmar convênio torna toda educação de trânsito opcional? Não. A faculdade é do instrumento cooperativo; os deveres do capítulo continuam.', 'O convênio está limitado à educação federal? Não. O artigo menciona órgãos de educação da União, Estados, Distrito Federal e Municípios.', 'Instrumento facultativo','Opção de cooperação para cumprir um dever que não se torna opcional.',notes=['Distinguir faculdade de celebrar convênio e obrigatoriedade das tarefas educacionais.'])
add(80,'Um município quer testar sinal inédito sem autorização federal. Resposta: o §2º atribui autorização experimental ao órgão máximo executivo da União, por período prefixado.', 'O supermercado de uso coletivo instala sinalização: o §3º atribui a responsabilidade ao proprietário, sem excluir condições de aprovação pertinentes.', 'Contran e órgão máximo executivo da União exercem a mesma função neste artigo? Não. O Contran fixa normas e especificações; a autorização experimental é do órgão máximo executivo federal.', 'A obrigação de instalar sinalização exclui áreas privadas de uso coletivo? Não. O §3º inclui vias de condomínios e vias/estacionamentos privados coletivos, sob responsabilidade do proprietário.', 'Experimento prefixado','Uso excepcional autorizado com duração definida, distinto de liberdade municipal para inventar sinais.',extra_points=['§3º: instalação em condomínio e estabelecimento privado coletivo é responsabilidade do proprietário.'],atencao=['A vedação geral deve ser lida com a exceção EXPERIMENTAL autorizada e de período PREFIXADO.','Lei 14.599/2023 atualizou o §2º; não atribuir autorização experimental indistintamente ao órgão local ou ao Contran.'],sources=[L14599])
add(81,'Um anúncio instalado em imóvel privado esconde a placa de parada obrigatória. Resposta: a proibição também alcança imóveis quando compromete visibilidade e segurança.', 'A propriedade privada não afasta o dever, mas o texto não proíbe toda vegetação ou toda publicidade sem considerar seu efeito na segurança viária.', 'A proibição só alcança elementos colocados na via pública? Não. O caput abrange vias públicas e imóveis no recorte de confusão, visibilidade e segurança.', 'Toda árvore ao lado de via é proibida só por existir? Não. Deve ser examinada a aptidão para gerar confusão, prejudicar sinalização e comprometer segurança, sem proibição universal de vegetação.', 'Interferência visual','Prejuízo à percepção da sinalização e à segurança por elementos externos.',notes=['Não converter o artigo em proibição geral de toda publicidade ou vegetação independentemente do risco descrito.'])
add(82,'Uma pessoa cola propaganda comercial no suporte de uma placa. Resposta: a vedação alcança sinalização, suportes e proximidade, não apenas a face da placa.', 'A indicação relacionada à própria mensagem da sinalização não se confunde com anúncio estranho afixado no suporte.', 'Publicidade no poste da placa está liberada porque não cobre a placa? Não. O artigo inclui respectivos suportes e elementos junto a ambos.', 'O artigo proíbe qualquer símbolo integrante da mensagem de trânsito? Não. A vedação recai em publicidade, inscrições, legendas e símbolos que não se relacionem com essa mensagem.', 'Mensagem da sinalização','Conteúdo pertinente ao sinal, distinto de propaganda estranha nele ou em seu suporte.',notes=['Preservar o requisito que não se relacionem com a mensagem; não excluir suportes da proteção.'])
add(83,'Um anunciante instala painel ao longo da via e busca autorização depois. Resposta: o artigo exige aprovação PRÉVIA pelo órgão com circunscrição.', 'Mesmo aprovado, o painel não ganha licença para ocultar sinalização ou comprometer segurança: integrar arts. 81 e 84.', 'A aprovação pode ser substituída por mera comunicação posterior? Não. O texto condiciona a afixação à prévia aprovação do órgão competente.', 'A aprovação afasta automaticamente a possibilidade de retirada por risco? Não. A segurança e a visibilidade continuam exigíveis, integrando os arts. 81 e 84.', 'Aprovação prévia','Controle anterior à afixação, sem imunidade diante de risco posterior.',notes=['Não tratar aprovação como licença absoluta para interferir na sinalização.'])
add(84,'Um painel prejudica a visibilidade da sinalização e a segurança. Resposta: o órgão pode retirar ou determinar retirada imediata, com ônus para quem o colocou.', 'Não confundir retirada do elemento obstrutivo com remoção de veículo nem criar neste artigo valor fixo de multa.', 'Somente quem instalou pode fisicamente retirar o obstáculo? Não. O órgão pode retirar diretamente ou determinar a retirada, conforme o caput.', 'O custo é necessariamente suportado pelo poder público? Não. O ônus recai sobre quem colocou o elemento prejudicial, segundo a regra textual.', 'Ônus da retirada','Encargo atribuído ao responsável que colocou o elemento prejudicial.',notes=['O artigo não fixa valor de multa nem confere competência indistinta a órgão sem circunscrição.'])
add(85,'O órgão destina um ponto da via à travessia de pedestres. Resposta: deve sinalizá-lo com faixas pintadas ou demarcadas no leito da via.', 'Após a demarcação, o dever de manutenção de visibilidade e segurança do art. 71 continua.', 'Basta designar administrativamente a travessia, sem demarcar? Não. O artigo exige sinalização com faixas pintadas ou demarcadas no leito da via.', 'A sinalização inicial dispensa manter a faixa visível? Não. Integrar o dever permanente de manutenção do art. 71, para conservar condições adequadas.', 'Demarcação da travessia','Indicação no leito da via da passagem destinada pelo órgão competente.',notes=['Não confundir sinalização inicial com dispensa do dever posterior de manutenção.'])
add(86,'Uma garagem de uso coletivo abre saída para a via sem identificação. Resposta: entradas e saídas precisam ser identificadas conforme regulamentação do Contran.', 'O artigo trata da identificação dos acessos; não concede preferência absoluta a quem sai da garagem.', 'Postos de gasolina e oficinas estão fora do rol? Não. O caput os inclui junto a estacionamentos e garagens de uso coletivo.', 'Identificar a saída elimina o dever de ceder aos demais usuários ao ingressar na via? Não. A identificação não afasta as regras de manobra e preferência aplicáveis, incluindo o art. 36.', 'Identificação do acesso','Indicação de entradas e saídas, distinta de regra de prioridade.',notes=['Não atribuir preferência automática ao veículo que sai do imóvel só porque o acesso está identificado.'])
add('86-a','Uma vaga com estacionamento regulamentado tem placa de destinação, mas omite informação sobre a infração por uso indevido. Resposta: o art. 86-A exige ambas as informações no seu recorte.', 'Vaga reservada a pessoa com deficiência ou idoso sem credencial exige integrar o inciso XX atual do art. 181; não chamar o inciso XVII de exclusivo das vagas especiais.', 'O inciso XVII do art. 181 refere-se exclusivamente a vagas de idosos e pessoas com deficiência? Não. Trata de desacordo com estacionamento regulamentado; o inciso XX atual tem a hipótese específica de vaga reservada sem credencial.', 'Basta informar a destinação, sem dados da infração por estacionamento indevido? Não. O art. 86-A exige placas de destinação e placas informando os dados sobre a infração.', 'Estacionamento regulamentado','Uso condicionado pela sinalização, distinto de uma única modalidade de vaga reservada.',simples='Vagas de estacionamento regulamentado referidas ao art. 181, XVII, exigem sinalização de destinação e informação sobre a infração por uso indevido. Não restringir todo inciso XVII a vagas de idosos ou pessoas com deficiência: a hipótese específica sem credencial consta atualmente do inciso XX do art. 181.',pontos=['Destinação da vaga sinalizada.','Informação sobre infração por estacionamento indevido.','Art. 181, XVII: estacionamento regulamentado; art. 181, XX: hipótese específica de vaga reservada sem credencial.'],atencao=['Incluído pela Lei 13.146/2015; integrar o inciso XX acrescentado pela Lei 13.281/2016. Não atualizar silenciosamente a remissão literal do art. 86-A nem ensinar enquadramento desatualizado.'])
add(87,'Uma placa, uma faixa pintada e um semáforo são apresentados numa questão. Resposta: pertencem, respectivamente, aos sinais verticais, horizontais e luminosos.', 'Gestos do condutor também entram no inciso VI; a categoria não se limita ao agente de trânsito.', 'Há seis incisos e o último se limita a gestos do agente? Não. Existem seis categorias, mas o inciso VI inclui gestos do agente e do condutor.', 'A classificação do art. 87 fixa sozinha a ordem de prevalência? Não. Categoriza sinais; a hierarquia entre ordens, semáforos, sinais e normas está no art. 89.', 'Categoria de sinal','Tipo de comunicação viária, distinto da sua posição de prevalência.',notes=['Distinguir classificação do art. 87 e hierarquia do art. 89.'])
add(88,'Após recapeamento, uma via pavimentada está sem sinalização horizontal adequada. Resposta: não pode ser reaberta até estar devidamente sinalizada vertical e horizontalmente.', 'Durante as obras, a sinalização específica adequada também é obrigatória, não só na futura entrega.', 'Basta sinalização vertical para reabrir via pavimentada após manutenção? Não. O caput exige vertical e horizontal, com condições adequadas de segurança.', 'O parágrafo dispensa sinais enquanto a obra ainda ocorre? Não. Determina sinalização específica e adequada nas vias ou trechos em obras.', 'Entrega segura','Liberação condicionada à sinalização adequada, distinta da proteção durante obras.',notes=['O caput trata de via PAVIMENTADA e de entrega/reabertura; não retirar esses recortes nem a obrigação durante obras.'])
add(89,'O semáforo está verde, mas o agente manda parar. Resposta: prevalece a ordem do agente sobre semáforo e outras normas ou sinais.', 'Sem agente ou semáforo determinando de outra forma, as indicações dos sinais prevalecem sobre normas gerais; segurança continua exigível.', 'Semáforo verde supera ordem expressa de parada do agente? Não. O inciso I coloca a ordem do agente acima das normas de circulação e outros sinais.', 'A prevalência permite atravessar de modo perigoso sem observar os demais usuários? Não. Resolve conflito de orientação, sem afastar o dever geral de cuidado e segurança.', 'Prevalência','Ordem legal para resolver orientações conflitantes na circulação.',notes=['Ordem de estudo: agente → semáforo → sinais → normas; não confundir com categorias do art. 87.'])
add(90,'A placa necessária para estabelecer uma restrição está incorreta e fundamenta autuação por desrespeito àquela sinalização. Resposta: o art. 90 afasta a sanção por essa inobservância no recorte descrito.', 'A mesma deficiência de placa não libera conduzir alcoolizado ou sem cinto: infrações independentes têm seus próprios requisitos.', 'Qualquer falha de sinalização elimina toda multa ocorrida na via? Não. O artigo trata de sanções por inobservância à sinalização insuficiente ou incorreta, não de imunidade geral.', 'Quem responde pela implantação e sua falta ou colocação incorreta? O órgão ou entidade com circunscrição sobre a via, conforme §1º, sem dispensar examinar responsabilidade concreta.', 'Inobservância da sinalização','Conduta cuja restrição depende do sinal, distinta de toda infração de trânsito.',atencao=['Não ensinar sinalização deficiente = nenhuma sanção por qualquer conduta. O nexo com a inobservância da sinalização é essencial.','Falta ou defeito de placa não autoriza embriaguez, falta de cinto ou outras condutas independentes.'])
add(91,'Dois órgãos adotam soluções de engenharia de tráfego. Resposta: devem observar normas e padrões nacionais estabelecidos pelo Contran.', 'A padronização não torna idênticas todas as condições locais nem elimina análise técnica da via na execução.', 'Cada município pode dispensar livremente os padrões nacionais? Não. O caput prevê normas e padrões para todos os órgãos e entidades do SNT.', 'Estabelecer normas de engenharia torna o Contran executor direto de toda obra? Não. O artigo atribui função normativa; execução e circunscrição têm distribuição própria.', 'Padrão nacional','Referência comum do Contran para soluções de engenharia de tráfego.',notes=['Distinguir padronização normativa e execução local competente.'])
assert len(rows)==50 and set(rows)==set(expected)
for key,row in rows.items():
 assert 'Variação:' in row['exemplo'] and len(row['prova'])==2,key
 assert all('?' in q and len(q.split('?',1)[1].strip())>45 for q in row['prova']),key
 assert row['termos'] and all(t['significado'] for t in row['termos'])
Path(sys.argv[2]).write_text(json.dumps({'course_slug':'transito','units':rows},ensure_ascii=False,indent=2)+'\n')
print('50 explicitly reviewed CTB units')
